import {personalityContent,personalityPage} from './personality.js?v=20261012-ren-depth1';
export const selfLayers=[
 {"id":"external-self","name":"外在角色我","place":"物质实相层／实相层","function":"在生活中感受、判断、表达与行动。","intro":"三者共同构成日常最熟悉的自己。我可以真实地经历它们，也可以观察、理解并回应它们；其中任何一个反应，都不必成为对完整自我的定义。","parts":["body-self","thinking-self","feeling-self"],"roles":["身体我提供感受与行动条件","头脑我组织理解与判断","情感我赋予需要与关系意义"],"pairs":[["身体 ↔ 头脑","身体状态影响注意与判断；头脑怎样解释处境，也会影响身体的紧张、舒展与行动准备。"],["头脑 ↔ 情感","解释影响感受，感受影响哪些问题显得重要。分析与感受互相校准，使判断既有依据，也回应真实需要。"],["情感 ↔ 身体","情感通过身体被体验、表达；身体的疲惫、舒适与节律，也参与当下的感受。"]],"result":"三者共同形成“我此刻怎样生活”：以身体参与，以头脑理解，以情感赋予分量，再组织成一次具体回应。","question":"我能否看见身体、头脑与情感的反应，而不让其中一项定义完整的自己？","practice":"将三种信息分别写清，再形成一个能够同时照顾它们的回应。","deep":"当我说“我累了”“我觉得他不尊重我”“我很难过”，身体状态、头脑解释与情感体验，已经共同进入了这个“我”。外在角色我，是生命在物质实相中感知、理解、回应并采取行动的日常面向。“外在”描述它所处的表达层面，并不表示虚假。疼痛是真的，悲伤是真的，正在发生的思考也是真的。认识这一层，不是把日常自己贬为需要摆脱的低级存在，而是看清：真实发生的经验，与经验对整个人的最终判决，是两回事。我们要完成的转变，是从自动认同反应，走向能够认识反应。身体有需要，头脑有解释，情感有所珍视；它们都值得被听见，也都需要放回具体处境中理解。"},
 {"id":"inner-role","name":"内在角色我","place":"模板层／电子层","function":"连接意识与实相，承接体验，支持角色运行。","intro":"位于模板层（电子层），在内在意识与日常体验到的外在角色之间，承担承接、组织与支持的中间作用。","parts":["heaven-soul","human-soul","earth-soul"],"roles":["意识承接：连接意识与角色体验","角色运作：支持生存、适应与持续运行","生命维系：支持身体的形成与生命活动"],"pairs":[["意识承接 ↔ 角色运作","意识的关注与意向需要通过具体角色展开。角色运作承接这些取向，同时回应所处环境；实际经历又带回新的信息，参与内在的理解与整合。"],["角色运作 ↔ 生命维系","角色的持续运行以身体的生命活动为基础。身体状态与需要进入角色的适应和回应，角色的活动也需要顾及维持生命的实际条件。"],["生命维系 ↔ 意识承接","身体使体验具有具体形式，意识通过角色接触这些经历。三个面向共同参与这一联系，不能理解成各自封闭、互不相关的部件。"]],"result":"三个面向相互配合：意识承接连接关注与体验，角色运作支持角色在环境中的持续参与，生命维系为身体的形成与运行提供内在支持。","question":"内在关注、角色的运行方式与身体条件，怎样在这次经历中相互联系？","practice":"从一件真实的事出发，分别看见自己珍视的方向、熟悉的反应模式和身体需要。再选择一个可以调整的部分，通过实际体验继续理解它们的关系。","deep":"内在角色我，是位于模板层（电子层）、连接内在意识与外在角色的内在结构。它承接意识的关注与意向，支持外在角色的形成和持续运行，也使角色的经历能够进入内在的体验与整合。我们从意识承接、角色运作与生命维系三个功能面向来理解这一层。它们共同描述中间层怎样发挥作用，并非三个彼此独立的“我”。"},
 {"id":"inner-consciousness","name":"内在意识我","place":"意识层 · 存在表达与主体性","function":"认识深层价值与生命方向，在不同表达中形成自主选择。","intro":"内在意识我，指向三道哲学对深层主体、价值与存在方向的理解。主导神格 A、次级神格 B 与 C，帮助我们辨认不同的存在表达，并在其中形成能够自主选择的整体。","parts":["godhead-a","godhead-b","godhead-c"],"roles":["A 辨认核心身份与主要方向","B 认识主轴之外的重要表达","C 认识第三种独特的存在表达"],"pairs":[["A ↔ B","主轴使选择具有方向，另一种重要表达也有自身的意义。统摄不要求把所有价值都变成服务单一目标的工具。"],["A ↔ C","第三种表达可以支持主轴，也可以提出被忽略的关切。主导需要听见差异，并根据经验修正自己的理解。"],["B ↔ C","两者都需要说清各自的价值、体验主题与创造倾向。C不是B之外剩下的可能，二者也不因次级而在存在价值上较低。"]],"result":"不同内在面向可以相互支持，也可以发生真实冲突。整合意味着理解差异、明确优先级，并由同一个人对选择与后果负责。","question":"我珍视什么，又怎样在不同的内在关切之间作出能够承担的选择？","practice":"回看一次价值冲突：各自珍视什么，实际选择由什么推动，承担了什么代价，怎样让下一步更符合深思熟虑后认可的方向。","deep":"认识身体、头脑和情感，让我们看见日常经验怎样形成。再往内追问，问题会变成：这些能力要表达什么？什么值得我长期投入？当需要与欲望彼此冲突，我依据什么选择？在三道哲学中，神格是内在意识的一种相对稳定、具有自身价值取向、体验主题与创造倾向的存在表达。它指向存在如何展开自身，不能直接缩减为一个性格标签、一种情绪或某项社会职务。A、B、C在这里是结构代号，没有被指定为具体神明、原型或固定品质。三者描述内在意识的不同面向，并非三个彼此独立、轮流控制身体的人格。"}
];

export const selfElements=[
 {"id":"body-self","name":"身体我","layer":"external-self","essence":"我以身体进入世界，身体也参与塑造我所经历的世界。","intro":"身体我是生命在物质世界中的具身存在。它使感知、体验与行动成为可能；理解身体，是认识自己此刻怎样存在、需要什么，以及能够怎样参与现实。","parts":[["感觉，是生命与现实相遇的入口","我们通过视觉、听觉、触觉、味觉和嗅觉感知环境，也通过饥饿、疲倦、心跳、疼痛等感受，接触身体内部的状态。世界不是只有被头脑描述之后，才进入生命；温度、节奏、距离与重量，已经在塑造体验。"],["身体状态，参与我们对世界的判断","连续睡眠不足时，集中注意、调节情绪和作出判断都可能更困难。同一个要求，可能在此时显得格外苛刻。身体并没有替世界改变全部事实，却改变了我们承受和解释事实的条件。"],["熟悉的反应，如何先于语言出现","有人面对质疑先屏住呼吸，有人遇到冲突立即后退，有人总在任务开始前紧绷起来。这些模式可能与气质、反复的生活经验和学习有关，不一定能归结为单一原因。"]],"distinction":"身体我描述实相层中的身体与其经验；生命维系描述本框架在模板层中对身体形成与生命活动的内在支持。两者在同一生命中相连，所讨论的层面不同。","example":"带回今天：我需要身体承担什么？它正在表达什么需要？哪一项安排可以更尊重这些条件？身体此刻的状态，不必定义我的全部价值与可能性。","questions":["身体觉察究竟在觉察什么？","如果身体会影响判断，我是不是不能相信自己的感受？","身体反应很快，是否意味着我没有选择？"]},
 {"id":"thinking-self","name":"头脑我","layer":"external-self","essence":"我能够理解世界，也能够检查自己正在怎样理解世界。","intro":"头脑我是通过记忆、概念、信念、推理和叙事，对世界与自我进行解释、预测和组织的认知系统。它的能力值得使用，它的结论也值得检验。","parts":[["头脑给出的，是对现实的理解","我们不可能每次都从零开始认识一切。头脑借助记忆与概念，使眼前的事物变得可以辨认、比较和安排。这种组织能力支持学习与合作，也意味着理解总包含取舍与解释。"],["我是谁，也可能是一个反复讲述的故事","自我概念，是我对自身特点、能力、品质与角色的理解；自我叙事，则是我如何把经历连成故事，解释自己为什么成为现在这样的人。二者使生命具有连续性，也可能把旧结论带到全新的处境中。"],["保护过我的判断，也可能把我留在过去","头脑会记住危险、羞辱与损失，并尝试避免它们重演。“不要依赖任何人”“必须足够强大才安全”，可能曾经帮助一个人撑过困难。理解这种保护意义，比简单责备自己想太多更接近真实。"]],"distinction":"头脑我与脑这个器官有关，但此处着眼于角色怎样使用思考。头脑我也与创造模型中的“思维”相连：前者是自我的一个面向，后者是落实创造的功能。","example":"头脑我是认知系统这一面向，信念是其中较稳定的理解与预期，思维是具体情境中展开的认知活动。认识头脑如何工作，为后续重新选择信念、开展思维和落实行动提供基础。","questions":["怎样分清事实、解释、预测与信念？","改变自我叙事，会不会变成替自己编一个好听的故事？","怎样看见身份背后隐藏的条件？"]},
 {"id":"feeling-self","name":"情感我","layer":"external-self","essence":"情绪让意义成为切身体验，也邀请我理解自己在乎什么。","intro":"情感我是生命对内外事件产生情绪性回应的体验面向。感受值得被承认，感受所包含的解释需要辨认，如何行动仍然需要选择。","parts":[["相同的事情，为什么带来不同的感受","一次公开评价，有人感到受鼓舞，有人感到被暴露；一次改变，有人体验自由，有人体验失去。事件与人的需要、价值、记忆和解释相遇，形成了不同的情感经验。"],["真实的感受，与准确的判断","“我感到被轻视”包含真实的受伤体验，也可能包含“他有意轻视我”的解释。承认前者，不要求未经核实就接受后者。"],["情绪背后，还可能有另一层感受","有时，我们先感到受伤，随后用愤怒保护自己；先体验恐惧，随后因为“不该害怕”而羞耻。后出现的情绪，可能使最初的需要更难被看见。"]],"distinction":"情感我采用“心理情感面向”的含义。资料中的“心识我”“内心我”等表达可以提供对照；其中“心智”还有贯穿更广阔意识整体的用法，需要依语境理解。","example":"认识自己中的情感我，讲情感怎样运作；接纳自己中的情绪接纳，讲怎样与真实感受相处；创造自己中的情绪要素，讲怎样使情绪参与所选择的生活。三处相连，各自回答不同的问题。","questions":["恐惧、愤怒、悲伤和羞耻，各自在告诉我什么？","如果我的解释错了，这份情绪是不是也错了？","怎样往下了解，又不替自己编造隐藏原因？"]},
 {"id":"heaven-soul","name":"意识承接","layer":"inner-role","essence":"承接内在意识与具体角色之间的联系。","intro":"意识承接是内在角色我面向意识层的一面。它使内在意识能够通过具体角色展开体验，也让角色的经历进入更广阔的理解与整合。","parts":[["承接关注","内在意识的关注与意向，通过模板层与一个具体角色发生联系。角色由此成为生命体验得以展开的表达。"],["连接体验","角色在身体、头脑与情感中经历生活；意识承接关注这些经历怎样与内在意识保持联系，而不只停在孤立的外在事件上。"],["支持整合","经历可以带来新的认识，也可能改变原先的关注方向。意识承接帮助我们理解由内向外表达、又由体验返回内在的关系。"]],"distinction":"意识承接属于模板层的中间作用；内在意识我属于意识层，是展开关注与体验的主体。两者分别回答“怎样连接”与“由谁关注和体验”，在整体中相连，不能直接视为同一层。","example":"一个人长期珍视创作，真正开始之后，却发现自己更在意与他人共同探索。可以借这一面向思考：内在关注怎样进入具体经历，经历又怎样使原先的自我理解变得更丰富。这是理解关系的生活例子。","questions":["我正在珍视怎样的方向或问题？","这份关注在具体经历中获得了什么内容？","有哪些新的体验，改变了我原先对自己的理解？"]},
 {"id":"human-soul","name":"角色运作","layer":"inner-role","essence":"支持角色的生存、适应与持续运行。","intro":"角色运作是内在角色我协调角色运行的一面。它连接内在取向、外在环境与生命条件，支持角色的生存、适应，以及已有运行模式的延续和调整。","parts":[["持续运行","日常生活包含许多已经熟悉的回应与模式，并非每一刻都从头作出全部决定。这个面向关注角色如何维持连贯的运行。"],["适应处境","环境与关系不断变化，角色需要回应新的条件。角色运作帮助我们理解内在取向、外在需要与实际反应之间的协调。"],["调整模式","熟悉的运行方式可以提供支持，也可能不再适合当前处境。新的体验与认识，为调整回应模式提供了可能。"]],"distinction":"角色运作属于模板层的运行面向；头脑我属于实相层的思考面向。前者关注角色怎样持续运作与适应，后者关注我们日常怎样分析、理解和计划。因此，角色运作的含义超出了安排日程与管理事务。","example":"受到质疑时，一个人可能还没有仔细分析，就已经急着辩解。看见这一熟悉模式后，可以练习先听清问题，再决定回应。日常可观察的是反应及其变化；这个面向为理解角色整体的运行提供哲学视角。","questions":["这件事里，哪些回应已经成为熟悉的模式？","这种模式正在帮助我适应什么，又忽略了什么？","新的处境需要我调整哪一种回应方式？"]},
 {"id":"earth-soul","name":"生命维系","layer":"inner-role","essence":"从生命群体的协作，理解身体的形成与运行。","intro":"生命维系是内在角色我支持身体生命活动的一面。在本框架中，它从构成身体的生命群体及其协作，理解肉身的形成、维持与运行。","parts":[["共同构成","身体作为一个整体，由许多相互关联的部分共同构成。这一面向从生命群体与复合体的视角，理解整体怎样获得组织。"],["维持运行","持续的生命活动为感受、表达与行动提供身体基础。生命维系关注这些活动在整体中的配合，而不只关注某一次有意识的动作。"],["进入体验","身体状态通过感受与需要进入日常经验。认识这一联系，有助于把身体条件纳入对完整生命的理解。"]],"distinction":"身体我描述实相层中日常可体验的身体、感官与行动能力；生命维系描述本框架在模板层中对身体形成与生命活动的内在支持。它们属于同一生命的不同观察层面。","example":"持续创作需要身体参与。疲惫、饥饿与休息需求，都应进入实际安排。可以从这些经验理解生命条件怎样支持参与，而不必把身体仅仅当作执行意志的工具。","questions":["这一次参与需要怎样的身体支持？","哪些生命需要正在通过感受进入我的注意？","怎样调整安排，能够更好地照顾这些条件？"]},
 {"id":"godhead-a","name":"主导神格 A","layer":"inner-consciousness","essence":"辨认我深层珍视的方向，再让选择成为它的表达。","intro":"A代表内在意识中当前最具统摄性的存在表达，关联核心身份、生命主题与主要方向。它提供认识的线索，具体内容仍需在体验中辨认，在选择中形成。","parts":[["什么值得成为生命的主轴","兴趣、欲望、才能和机会可以很多，生命主轴关切的是：在变化的生活中，我反复被什么意义吸引，愿意让什么组织自己的投入与取舍？"],["社会身份，是表达方式，不是全部存在","企业家、教师、研究者、作家，说明人在社会中承担什么角色。角色可以承载深层价值，却不能仅凭名称说明一个人为何投入，以及愿意成为怎样的人。"],["强烈的追求，可能同时包含价值与保护","“我必须强大，否则就不安全”，与“我愿意拥有力量，以承担更大的责任”，可能产生相似的外在成就，却以不同的内在理由组织生活。前者主要防御威胁，后者指向愿意实现的价值。"]],"distinction":"A、B、C是存在表达的结构代号，不预设神明、性格或职业。主导与次级描述关系位置，不决定价值高低，也不把人分成轮流控制身体的独立人格。","example":"今天可以回看一个真实决定：我声称珍视的是什么？实际选择由什么推动？下一步怎样使两者更一致，同时承认我仍有其他重要的需要？","questions":["主轴与天赋、兴趣有什么区别？","如果不再拥有熟悉的身份，我还能从哪里认识自己？","怎样辨认自己追求的是价值，还是理想带来的荣耀？"]},
 {"id":"godhead-b","name":"次级神格 B","layer":"inner-consciousness","essence":"主导不等于唯一，生命也不必被压缩成一种意义。","intro":"B代表不能被主导神格A完全涵盖、却具有自身价值与创造倾向的另一种内在表达。次级描述当前关系位置，不表示它只配作为主要目标的辅助。","parts":[["为什么一个主轴不能说明全部生命","一个人可以长期投入严肃的事业，同时珍视亲密、审美、游戏或自由探索。这些体验并不因为没有直接提高事业效率，就失去意义。"],["允许另一种价值，以自身的理由存在","如果休息只为了更有效地工作，关系只为了得到支持，游戏只为了激发创新，那么看似丰富的生活仍可能只允许一个目标拥有最终意义。"],["冲突可以显现不同的真实需要","想维持稳定，又想探索新方向；希望承担责任，也需要自己的空间。这些冲突不一定意味着其中一方虚假，可能只是有限的时间、精力与关系条件，使两个价值无法同时被充分满足。"]],"distinction":"A、B、C是存在表达的结构代号，不预设神明、性格或职业。主导与次级描述关系位置，不决定价值高低，也不把人分成轮流控制身体的独立人格。","example":"内在的丰富，需要被认识，也需要被安排。承认B的意义，使主轴拥有深度，而不必把生命变成一条只有产出的路线。","questions":["B是不是与A相反的性格？","承认多种价值，会不会让人失去专注？","我怎样知道这是另一种深层表达，而不是一次逃避？"]},
 {"id":"godhead-c","name":"次级神格 C","layer":"inner-consciousness","essence":"认识另一种独特的存在表达，不让它被归入模糊的“其他”。","intro":"C是本框架中第三个需要具体理解的内在面向。它具有自身的价值取向、体验主题与创造倾向，不能仅被解释为B之外剩下的可能，也不因位置靠后而较不重要。","parts":[["第三个位置，必须有独特的意义","把某一面向单独称为C，需要它确实增加理解：它主要珍视什么，愿意进入怎样的体验，又倾向于创造什么？如果这些都只是B在另一处境中的重复，就没有必要仅为了填满结构而另设一个名称。"],["给它自身的主题，而不只给它一个功能","若一种表达只能被描述为“帮助A完成目标”或“在A、B冲突时调和”，它自身为什么值得便仍未被说清。C可以产生支持与协调的作用，但这些作用不能代替存在的意义。"],["七个维度，辨认C自己的表达","核心本质问“这个面向主要怎样存在”；核心价值问“它自身珍视什么”；体验主题问“它反复关切什么课题”；创造倾向问“它希望展开什么可能”。这些问题应当得到能够与A、B比较的具体回答。"]],"distinction":"A、B、C是存在表达的结构代号，不预设神明、性格或职业。主导与次级描述关系位置，不决定价值高低，也不把人分成轮流控制身体的独立人格。","example":"回到一次实际选择：我听见了哪些关切，哪一种长期没有被认真表达，怎样让它获得经验，又怎样承担由此带来的调整？内在的统一，就在这样的认识与选择中逐渐形成。","questions":["怎样判断它与B有实质区别？","是不是每一种新兴趣，都说明出现了新的神格？","如果七个问题暂时没有答案，怎么办？"]}
];

const crumbs=(tail='')=>`<nav class="breadcrumbs" aria-label="当前位置"><a href="#/">首页</a><span>/</span><a href="#/ren">人道</a><span>/</span>${tail?'<a href="#/knowing">认识自己</a><span>/</span><span aria-current="page">'+tail+'</span>':'<span aria-current="page">认识自己</span>'}</nav>`;
const cards=(items)=>`<div class="kn-three">${items.map(([t,p])=>`<div><h3>${t}</h3><p>${p}</p></div>`).join('')}</div>`;
const related=(layer)=>`<div class="kn-related">${layer.parts.map(id=>{const e=selfElements.find(e=>e.id===id);return `<a href="#/knowing/${id}">${e.name} ↗</a>`;}).join('')}</div>`;
const structure=(layer,i)=>`<details class="kn-layer-fold" id="kn-layer-${layer.id}"><summary><span class="eyebrow">0${i+2} / 层内结构</span><span><strong>${layer.name}</strong><small>${layer.intro}</small></span><b aria-hidden="true">＋</b></summary><div class="kn-layer-content"><div class="kn-role-line">${layer.roles.map(r=>`<span>${r}</span>`).join('')}</div>${cards(layer.pairs)}<div class="kn-result"><h3>共同作用</h3><p>${layer.result}</p></div><p class="kn-prompt">${layer.question}</p><a class="text-link" href="#/knowing/${layer.id}">深入理解${layer.name} ↗</a></div></details>`;
const sourceNote=()=>`<details class="kn-sources"><summary>思想来源与术语</summary><div><h3>三个“我”的框架</h3><p>外在角色我、内在角色我、内在意识我，是《三道哲学》认识自己的核心结构。三者描述同一生命相互关联、共同运作的层面，“＋”表示共同构成。意识层对应内在意识我，模板层（也称电子层）对应内在角色我，物质实相层对应外在角色我；物质实相层在“创造自己”中简称实相层。</p><h3>功能名称与原有术语</h3><p>本页以意识承接、角色运作、生命维系，分别作为理解原有“天魂、人魂、地魂”的功能入口。它们是内在角色我同一层中的三个面向，不是再划分出的三个层次，也不把原材料中的人格、载具与生命群体全部化约成单一功能。</p><p>相关定义与功能名称由《三道哲学》组织表述，并非细雨或赛斯的逐字原话。Y6-2第259节的细雨译解文本将人魂联系到“生存人格”及角色的持续运行，因此这里使用“角色运作”，避免将其缩减为日程或事务管理。译文与点评依各自语境理解，不将整段译解一概署为赛斯原话。</p><h3>神格的用法</h3><p>神格对应细雨灵性语境中的“人格”；主神格对应“主人格”；次级神格对应其他“人格片段”。本页以主导神格 A、次级神格 B、C描述当前意识群体的关系。阅读更宏观的谱系时，需要同时辨认所讨论的群体尺度。</p><h3>细雨资料</h3><p>Y3-4：意识复合体与协同；Y3-5：角色与意识；Y5-3、Y7-5：身体、头脑与心理面向；Y7-1：外在角色与内在角色；Y6-2 第255节、Y3-4 第119节、Y9-1：多重表达、协作与动态主导。相关术语依各处讨论的层次理解。</p><h3>阅读尺度</h3><p>模板层（电子层）、纯意识本体与神格群体，属于这里采用的世界观。日常练习以身体感受、判断、关系、选择与行动进入体验；哲学解释与可观察的经验各自保留其意义。</p></div></details>`;

const compactStructure=(active='')=>`<section class="kn-compact" aria-label="三个我的完整结构"><p class="kn-compact-formula">我 = 外在角色我 + 内在角色我 + 内在意识我</p><div class="kn-compact-table">${selfLayers.map(l=>`<div class="kn-compact-row${l.id===active?' is-current':''}"><a class="kn-compact-label" href="#/knowing/${l.id}" ${l.id===active?'aria-current="page"':''}>${l.name}</a><div class="kn-compact-parts">${l.parts.map(id=>{const e=selfElements.find(e=>e.id===id);return `<a href="#/knowing/${id}">${e.name}</a>`;}).join('')}</div></div>`).join('')}</div></section>`;

export function knowingPage(){return `<div class="page-shell knowing-page kn-framework">${crumbs()}<header class="kn-head"><p class="eyebrow">人道 / 认识自己</p><h1>认识自己</h1><p class="kn-intro">外在角色我处于物质实相层，是日常接触到的自己；内在角色我处于模板层，承担承接与组织的中间作用；内在意识我处于意识层，展开关注与体验。三个层面共同构成完整的生命。</p></header>
${compactStructure()}
${selfLayers.map(structure).join('')}
<section class="kn-section"><span class="eyebrow">05 / 三层如何协同</span><h2>由内向外表达，由体验深化认识。</h2><div class="kn-flow">${[selfLayers[2],selfLayers[1],selfLayers[0]].map((l,i)=>`<div><span>${['方向与探索','承载与连接','体验与行动'][i]}</span><h3>${l.name}</h3><p>${l.function}</p></div>`).join('')}<p>↶ 日常经历进入内在整合，新的认识再参与下一次选择。</p></div><p class="kn-body">认识自己的核心，是逐渐看清各层的作用及其关系。身体需要、头脑判断、情感诉求与更长远的生命方向，都需要在实际生活中获得协调。看见之后，我们可以接纳真实的自己，也可以选择怎样继续成为。</p><div class="kn-example"><h3>想开始一项珍视的创作，却迟迟没有行动</h3><p><strong>外在角色我：</strong>身体疲惫，头脑担心做不好，情感希望被认可。先把三种信息分别看清。</p><p><strong>内在角色我：</strong>从内在关注怎样进入体验、熟悉模式怎样影响回应、身体条件怎样支持参与，理解这件事。再以可观察的经验为起点，调整实际的参与方式。</p><p><strong>内在意识我：</strong>为熟悉的自我画像之外保留可能，探索自己为何珍视创作，以及还有怎样的能力值得展开。</p><p>从一个段落或一个小样开始。实践之后，回看真实经验：哪些需要得到照顾，哪个判断需要修正，自己又显现了什么新的可能。</p></div><div class="kn-related"><a href="#/awareness">通过觉察认识自己 ↗</a><a href="#/becoming/identity">通过体验，理解身份 ↗</a><a href="#/becoming">通过选择，创造自己 ↗</a></div></section>
<details class="kn-deep"><summary>深入阅读：载具、本体与贯穿各层的连接</summary><div class="kn-prose"><h3>意识承接与内在意识：连接和主体</h3><p>意识承接属于模板层中的连接面向，神格属于内在意识我的意识表达。两者分别帮助我们理解“怎样连接”与“由谁关注和体验”。模板层也称电子层，处于意识与物质角色之间。</p><h3>身体我与生命维系：表达层与意识基础</h3><p>身体我是日常可体验的肉身面向；生命维系是本框架对其生命活动的内在意识基础所作的解释。它们指向同一生命在不同层面的关系，九格因此是理解入口，而非九个彼此隔绝的部件。</p><h3>主导与次级：生命主轴与不同存在表达</h3><p>A帮助辨认核心身份与主要方向，B与C各有不能被主轴完全涵盖的价值、体验主题与创造倾向。C不是其他可能的总称。整合使不同面向被听见，也使同一个人能够明确优先级、承担选择，并在新经验中修正理解。</p><h3>心智与潜意识：贯穿，而非再加一格</h3><p>资料把心智描述为贯穿自我群体的内在根脉，把潜意识描述为沟通与转译的桥梁。它们用于解释各层怎样连接，不宜仅为满足格数而塞入某一层。情感我采用心理情感的含义，不穷尽这些更广泛的“心智”用法。</p><h3>更宏观的谱系</h3><p>本源、万有／万存、超我、本我、高我及其分化，可以在天道与多维意识的讨论中继续展开。认识自己先以三个“我”看清当前结构，再沿着内在连接理解更广阔的存在。</p><a class="text-link" href="#/concept/blueprint">继续阅读生命蓝图 ↗</a></div></details>
${sourceNote()}<a class="kn-next" href="#/ren">返回人道 <span>→</span></a></div>`;}

const innerRoleReadings={
  "inner-role": [
    [
      "为什么在意识与物质角色之间，还需要理解一个模板层？",
      [
        "在三道哲学中，意识层、模板层与物质实相层，分别帮助我们理解关注的主体、承接和组织的结构，以及实际被经历的表达。内在角色我位于中间，关注的是意识怎样与具体角色相连、角色怎样获得持续运行的支持。",
        "“模板”并不只指一张静止的设计图。这里还包含承接、组织、协调与反馈：内在关注通过角色展开，角色遇见环境、身体和他人，实际经历又进入内在整合。理解这一层，需要同时看两个方向。",
        "因此，不能把内在角色我缩减为外在头脑的计划，也不能直接把它等同于意识主体。三个层面共同描述同一生命，彼此之间的联系，比单独记住每个名称更重要。"
      ]
    ],
    [
      "三个功能面向，是三个彼此独立的“我”吗？",
      [
        "这里采用“功能面向”的说法，是为了先让读者理解各自承担的作用：意识承接侧重与意识层的联系，角色运作侧重生存与适应，生命维系侧重身体的形成与运行。",
        "它们并不是再向下划分出的三个层次，也不是各自封闭的三个小人。一次具体体验可以同时涉及三个面向。比如进入一段新的合作，既有内在关注的投入，也有熟悉模式对新环境的适应，还需要身体条件的支持。",
        "这种功能表述没有要求我们把原资料中的人格、载具与生命群体，全部化约成没有其他含义的抽象功能。它提供一个阅读入口；希望追溯原有术语时，可以继续展开文末的说明。"
      ]
    ],
    [
      "怎样把这个结构带回生活，又不急着解释一切？",
      [
        "可以从日常确实能够接触的体验开始：这件事为什么吸引我，我怎样习惯性地回应，身体正在传递什么需要？把这些信息放在一起，往往比立即给某一层下判断更有帮助。",
        "例如，一个人想表达不同意见，却总是抢先附和。可以先了解自己珍视什么、担心什么，辨认熟悉的回应方式，再留意紧张如何在身体中被体验。下一次尝试一种更合适的表达，实际回应也会带来新的认识。",
        "这些观察可以帮助认识自己，但不能仅凭一次直觉、一个习惯或一种身体感受，就判定它必定由哪一层单独造成。这里的层次是三道哲学的理解框架，生活中的具体问题仍需要具体了解。"
      ]
    ]
  ],
  "heaven-soul": [
    [
      "意识承接与内在意识我，最关键的区别是什么？",
      [
        "内在意识我讨论意识主体怎样展开关注、探索与经验整合；意识承接讨论这份关注怎样与具体角色的体验建立联系。一个位于意识层，一个位于模板层，理解的对象不同。",
        "可以借表达来作有限的比喻：创作者、表达所需的组织与媒介、最后可以被感知的作品，彼此相连，却不能完全混成一件事。这个比喻只帮助说明关系，不用来证明生命的全部运行机制。",
        "因此，意识承接不能代替内在意识我，也不等于外在头脑对某件事的集中注意。它在本框架中的重点，是连接角色体验与更内在的意识表达。"
      ]
    ],
    [
      "日常的灵感与直觉，可以怎样放在这里理解？",
      [
        "一种突然浮现的方向、一段尚未成句的理解，可能让我们感觉自己还有未被充分认识的部分。可以把它记录下来，看看它与持续的关注、实际经历和已有材料怎样相连。",
        "不过，灵感或直觉的出现本身，不能独立证明它来自某个确定层次。它也可能包含联想、记忆与当下感受，需要在具体内容中继续分辨。",
        "这个面向鼓励为更广阔的自我理解留出空间，同时让理解进入生活：这份灵感值得怎样探索，需要核实什么，实际尝试后又发现了什么？关注与体验便有了继续往返的机会。"
      ]
    ]
  ],
  "human-soul": [
    [
      "角色运作为什么不等于头脑思考或日程管理？",
      [
        "头脑思考通常可以从日常经验直接观察：正在比较两个方案、回忆信息、形成解释或安排计划。角色运作则是本框架对角色整体如何持续运行、形成熟悉模式并适应环境的理解。",
        "许多时候，人并未逐项分析，就已经采用熟悉的方式说话、应对关系或完成活动。对这些连贯性的讨论，范围比显性的计划更广。把人魂改称“日常统筹”，容易让读者误以为这里只是在谈管理时间。",
        "两者也不是互不相关。新的思考与实践可能改变熟悉的回应，已有模式也会影响头脑首先注意什么、怎样解释。分清层次，是为了更好理解联系。"
      ]
    ],
    [
      "熟悉的运行模式，会不会决定我只能成为原来的自己？",
      [
        "熟悉模式能够减少每次重新摸索的需要，但有些模式也会在条件变化后显得局限。看见它们，可以让原本自动发生的回应多出被理解与调整的空间。",
        "例如，以前迅速答应别人，可能帮助一个人维持关系；后来责任增加，这种方式却使自己难以履约。理解它曾经的作用，再学习询问需求、说明范围与适当拒绝，比简单否定过去的自己更完整。",
        "这个框架允许我们理解稳定与变化同时存在。改变未必立即发生，也可能需要关系、资源与环境的支持；一次旧反应出现，不意味着全部学习都失去了意义。"
      ]
    ]
  ],
  "earth-soul": [
    [
      "生命维系与身体我，为什么要分开放？",
      [
        "身体我着眼于我们日常能够经历的身体：感官、需要、动作，以及通过身体参与世界的方式。生命维系则放在模板层中，讨论支撑身体形成和运行的内在组织关系。",
        "例如，感到疲惫，是身体经验；怎样理解许多生命活动共同维持一个身体，则属于另一个层面的追问。两个面向可以指向同一生命，而不必使用同一种解释尺度。",
        "这种区分是三道哲学的组织方式。原材料关于微粒意识与生命群体的讨论属于其哲学语境，不能直接与某一个生理系统逐项等同。"
      ]
    ],
    [
      "这会怎样改变我们对待身体的方式？",
      [
        "它邀请我们把身体看作需要持续照顾的生命整体。身体的参与有条件，感受与需要也值得进入计划，而不只是等事情做完之后才被注意。",
        "在日常中，可以从具体的配合开始：安排适当休息，调整过量任务，理解自己当前能够承担的活动，并在需要时寻找合适帮助。这些照顾不需要先完成全部哲学判断。",
        "身体状态也不能用来给一个人的意识或价值评分。认识身体的复杂与相互依赖，可以使我们更有耐心地理解实际条件，并选择怎样参与生活。"
      ]
    ]
  ]
};
const deeper=id=>{const items=innerRoleReadings[id];return items?`<section class="kn-section"><span class="eyebrow">深入理解</span><h2>从几个问题，继续理解。</h2>${items.map(([q,ps])=>`<details class="kn-deep"><summary>${q}</summary><div class="kn-prose">${ps.map(p=>`<p>${p}</p>`).join('')}</div></details>`).join('')}</section>`:'';};


export function selfLayerPage(id){if(personalityContent[id])return personalityPage(id,selfLayers,selfElements,compactStructure);const l=selfLayers.find(x=>x.id===id);if(!l)return '';return `<div class="page-shell knowing-page kn-reading">${crumbs(l.name)}<header class="kn-head"><p class="eyebrow">认识自己 / ${l.place}</p><h1>${l.name}</h1><p class="kn-intro">${l.intro}</p></header>${compactStructure(id)}<section class="kn-section"><span class="eyebrow">01 / 这一层是什么</span><h2>${l.function}</h2><p class="kn-body">${l.deep}</p></section><section class="kn-section"><span class="eyebrow">02 / 三个面向</span>${cards(l.parts.map(id=>{const e=selfElements.find(x=>x.id===id);return [e.name,e.intro];}))}${related(l)}</section><section class="kn-section"><span class="eyebrow">03 / 怎样共同作用</span>${cards(l.pairs)}<div class="kn-result"><h3>共同作用</h3><p>${l.result}</p></div></section><section class="kn-section"><span class="eyebrow">04 / 带回生活</span><h2>${l.question}</h2><p class="kn-body">${l.practice}</p><a class="text-link" href="#/awareness">进入觉察训练 ↗</a></section>${deeper(id)}${sourceNote()}<a class="kn-next" href="#/knowing">返回三个“我”的结构 <span>→</span></a></div>`;}

export function selfElementPage(id){if(personalityContent[id])return personalityPage(id,selfLayers,selfElements,compactStructure);const e=selfElements.find(x=>x.id===id);if(!e)return '';const l=selfLayers.find(x=>x.id===e.layer);return `<div class="page-shell knowing-page kn-reading">${crumbs(e.name)}<header class="kn-head"><p class="eyebrow">${l.name} / ${l.place}</p><h1>${e.name}</h1><p class="kn-essence">${e.essence}</p><p class="kn-intro">${e.intro}</p></header><section class="kn-section"><span class="eyebrow">01 / 理解这个面向</span>${cards(e.parts)}</section><section class="kn-section"><span class="eyebrow">02 / 在整体中的位置</span><h2>放回${l.name}，理解它的作用。</h2><p class="kn-body">${e.distinction}</p><p class="kn-body">${l.result}</p>${related(l)}<a class="text-link" href="#/knowing/${l.id}">理解这一层的内部结构 ↗</a></section><section class="kn-section"><span class="eyebrow">03 / 带回体验</span><p class="kn-body">${e.example}</p><ol class="kn-questions">${e.questions.map(q=>`<li>${q}</li>`).join('')}</ol><a class="text-link" href="#/practice">记录一次真实选择 ↗</a></section>${deeper(id)}${sourceNote()}<a class="kn-next" href="#/knowing">返回三个“我”的结构 <span>→</span></a></div>`;}

export function initKnowing(){document.querySelectorAll('.kn-layer-fold').forEach(d=>d.addEventListener('toggle',()=>{d.querySelector('summary>b').textContent=d.open?'−':'＋';}));}
